print("Lowest: {} {}".format(worst[0], worst[1]))
for g in "ABCDF":
    print(g, len(list(filter(lambda v: band(v) == g, values))))
print("Below average:")
for name in map(lambda e: e[0], filter(lambda e: e[1] < average, entries)):
    print(name)

