    static String richest() {
        String who = null;
        for (Map.Entry<String, double[]> entry : payroll.entrySet()) {
            if (who == null || entry.getValue()[3] > payroll.get(who)[3]) {
                who = entry.getKey();
            }
        }
        return who;
    }

