}

long total(const int *p, int n) {
    long t = 0;
    const int *end = p + n;
    while (p < end) t += *p++;
    return t;
}

void extremes(const int *p, int n, int *hi, int *lo) {
    *hi = *lo = *p;
    for (const int *q = p + 1; q < p + n; q++) {
        if (*q > *hi) *hi = *q;
        if (*q < *lo) *lo = *q;
    }
}

