}

int maximum(int a[], int n) {
    int m = a[0];
    for (int i = 1; i < n; i++)
        if (a[i] > m) m = a[i];
    return m;
}

int minimum(int a[], int n) {
    int m = a[0];
    for (int i = 1; i < n; i++)
        if (a[i] < m) m = a[i];
    return m;
}

int secondLargest(int a[], int n, int *found) {
    int max = maximum(a, n), second = 0;
    *found = 0;
    for (int i = 0; i < n; i++) {
        if (a[i] != max && (!*found || a[i] > second)) {
            second = a[i];
            *found = 1;
        }
    }
    return second;
}

int isPalindrome(int a[], int n) {
    for (int i = 0; i < n / 2; i++)
        if (a[i] != a[n - 1 - i]) return 0;
    return 1;
}

